<?php
defined( 'ABSPATH' ) || exit;
final class SWC_Frontend {
	public function hooks(){add_shortcode('swc_worldwide_clinic',array($this,'clinic'));add_shortcode('swc_request_appointment',array($this,'request'));add_shortcode('swc_my_appointments',array($this,'patient'));add_shortcode('swc_doctor_appointments',array($this,'doctor'));add_shortcode('swc_doctor_availability',array($this,'availability'));add_filter('do_shortcode_tag',array($this,'augment'),10,2);}
	public function clinic(){ $p=SWC_Helpers::pages();$doctors=SWC_Helpers::doctor_ids();ob_start();?><main class="swc-shell"><?php echo SWC_Helpers::navigation();// phpcs:ignore ?><header class="swc-hero"><div><span>Responsible Global Access</span><h1>Worldwide Clinic</h1><p>Request an online or in-person appointment with a verified practitioner. This service is not emergency care and does not guarantee diagnosis, treatment, or outcomes.</p><div class="swc-hero-actions"><a class="swc-button" href="<?php echo esc_url(!empty($p['request'])?get_permalink($p['request']):'#');?>">Request an Appointment</a><a class="swc-button swc-light" href="<?php echo esc_url(!empty($p['patient'])?get_permalink($p['patient']):'#');?>">My Appointments</a></div></div><aside><strong>Emergency warning</strong><p>If you may be experiencing a medical emergency, contact your local emergency services immediately. Do not wait for an online appointment.</p></aside></header><section class="swc-steps"><article><b>1</b><h2>Choose a Doctor</h2><p>Review a verified public profile and consultation availability.</p></article><article><b>2</b><h2>Request a Time</h2><p>Log in and submit a preferred date, time, time zone, and contact details.</p></article><article><b>3</b><h2>Receive Confirmation</h2><p>The doctor may accept, decline, or request another time.</p></article></section><section class="swc-section"><div class="swc-section-head"><div><span>Verified Professionals</span><h2>Available Doctors</h2></div></div><div class="swc-grid"><?php if($doctors):foreach($doctors as $id){echo $this->doctor_card($id);}else:?><div class="swc-empty">No verified doctors have published clinic availability yet.</div><?php endif;?></div></section><p class="swc-disclaimer">Appointments do not establish emergency coverage. Confirm professional licensing, fees, scope, and suitability directly before care.</p></main><?php return ob_get_clean();}
	private function doctor_card($id){$u=get_userdata($id);if(!$u){return '';}$online='1'===SWC_Helpers::doctor_meta($id,'online','0');$person='1'===SWC_Helpers::doctor_meta($id,'in_person','0');$unavailable='1'===SWC_Helpers::doctor_meta($id,'unavailable','0');$p=SWC_Helpers::pages();$request=!empty($p['request'])?add_query_arg('doctor',$id,get_permalink($p['request'])):'#';$photo=absint(SPD_Helpers::get($id,'profile_photo_id',0));ob_start();?><article class="swc-card"><div class="swc-avatar"><?php echo $photo?wp_get_attachment_image($photo,'thumbnail',false,array('alt'=>$u->display_name,'loading'=>'lazy')):esc_html(SDD_Helpers::initials($u->display_name));?></div><span class="swc-badge">✓ Verified Doctor</span><h3><a href="<?php echo esc_url(SDD_Helpers::profile_url($id));?>"><?php echo esc_html($u->display_name);?></a></h3><p><?php echo esc_html(trim(SPD_Helpers::get($id,'city').', '.SPD_Helpers::get($id,'country'),', '));?></p><div class="swc-tags"><?php if($online):?><span>Online</span><?php endif;?><?php if($person):?><span>In person</span><?php endif;?><span><?php echo $unavailable?'Temporarily unavailable':('1'===SWC_Helpers::doctor_meta($id,'accepting','0')?'Accepting requests':'Availability limited');?></span></div><a class="swc-button <?php echo $unavailable?'is-disabled':'';?>" href="<?php echo $unavailable?'#':esc_url($request);?>" <?php echo $unavailable?'aria-disabled="true"':'';?>>Request Appointment</a></article><?php return ob_get_clean();}
	public function request(){if(!is_user_logged_in()){return '<div class="swc-notice"><h2>Log in to request an appointment</h2><p>You may browse the clinic publicly, but an account is required to submit private contact information.</p><a class="swc-button" href="'.esc_url(wp_login_url(get_permalink())).'">Log In</a></div>';}$ids=SWC_Helpers::doctor_ids();$selected=isset($_GET['doctor'])?absint($_GET['doctor']):0;$u=wp_get_current_user();$zone=wp_timezone_string();if(!in_array($zone,SWC_Helpers::timezones(),true)){$zone='UTC';}ob_start();?><main class="swc-shell"><header class="swc-page-head"><span>Private Appointment Request</span><h1>Request an Appointment</h1><p>Provide only the minimum information needed to review scheduling.</p></header><div class="swc-emergency"><strong>Emergency warning</strong><p>If symptoms may be life-threatening, severe, or rapidly worsening, contact local emergency services now. Do not submit this form.</p></div><form class="swc-form" action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><input type="hidden" name="action" value="swc_submit_appointment"><?php wp_nonce_field('swc_submit_appointment','swc_nonce');?><label>Verified doctor<select name="doctor_id" required><option value="">Choose a doctor</option><?php foreach($ids as $id):?><option value="<?php echo absint($id);?>" <?php selected($selected,$id);?>><?php echo esc_html(get_the_author_meta('display_name',$id));?></option><?php endforeach;?></select></label><label>Consultation type<select name="consultation_type" required><option value="online">Online consultation</option><option value="in-person">In-person consultation</option></select></label><label>Preferred date<input type="date" name="preferred_date" min="<?php echo esc_attr(gmdate('Y-m-d',time()+DAY_IN_SECONDS));?>" required></label><label>Preferred time<input type="time" name="preferred_time" required></label><label>Patient time zone<select name="patient_timezone" required><?php foreach(SWC_Helpers::timezones() as $tz):?><option value="<?php echo esc_attr($tz);?>" <?php selected($zone,$tz);?>><?php echo esc_html($tz);?></option><?php endforeach;?></select></label><label>Country<input name="country" value="<?php echo esc_attr(get_user_meta($u->ID,'_sa_country',true));?>" required></label><label>City<input name="city" value="<?php echo esc_attr(get_user_meta($u->ID,'_sa_city',true));?>"></label><label>Phone number<input name="phone" inputmode="tel" value="<?php echo esc_attr(get_user_meta($u->ID,'_sa_phone',true));?>" placeholder="+12025550123" required></label><label>WhatsApp number<input name="whatsapp" inputmode="tel" placeholder="+12025550123" required></label><label>Duration of concern<input name="duration" maxlength="120" placeholder="For example: three days"></label><label class="swc-wide">General reason for consultation<textarea name="reason" maxlength="1500" required placeholder="Briefly describe the scheduling concern. Do not upload records or include unnecessary sensitive details."></textarea></label><label class="swc-check swc-wide"><input type="checkbox" name="emergency_confirm" value="1" required> I understand that this service is not for emergencies.</label><label class="swc-check swc-wide"><input type="checkbox" name="consent" value="1" required> I consent to sharing this request and my contact details with the selected doctor and authorized clinic administrators.</label><button class="swc-button" type="submit">Submit Appointment Request</button></form></main><?php return ob_get_clean();}
	public function patient(){if(!is_user_logged_in()){return '<div class="swc-notice"><a class="swc-button" href="'.esc_url(wp_login_url(get_permalink())).'">Log In to View Appointments</a></div>';}$items=get_posts(array('post_type'=>SWC_Helpers::TYPE,'post_status'=>'publish','author'=>get_current_user_id(),'posts_per_page'=>100,'orderby'=>'date','order'=>'DESC'));return $this->dashboard('My Appointments',$items,'patient');}
	public function doctor(){if(!is_user_logged_in()||!SDD_Helpers::is_verified(get_current_user_id())){return '<div class="swc-notice">Verified doctor access is required.</div>';}$items=get_posts(array('post_type'=>SWC_Helpers::TYPE,'post_status'=>'publish','posts_per_page'=>200,'meta_key'=>'_swc_doctor_id','meta_value'=>get_current_user_id(),'orderby'=>'date','order'=>'DESC'));return $this->dashboard('Doctor Appointments',$items,'doctor');}
	private function dashboard($title,$items,$role){ob_start();?><main class="swc-shell"><header class="swc-page-head"><span>Private Clinic Dashboard</span><h1><?php echo esc_html($title);?></h1></header><div class="swc-list"><?php if($items):foreach($items as $a):echo $this->appointment_card($a,$role);endforeach;else:?><div class="swc-empty">No appointments found.</div><?php endif;?></div></main><?php return ob_get_clean();}
	private function appointment_card($a,$role){$id=$a->ID;$doctor=absint(SWC_Helpers::meta($id,'doctor_id'));$patient=absint($a->post_author);$status=SWC_Helpers::status($id);$zone='doctor'===$role?SWC_Helpers::doctor_meta($doctor,'timezone','UTC'):SWC_Helpers::meta($id,'patient_timezone','UTC');ob_start();?><article class="swc-appointment"><header><span class="swc-status is-<?php echo esc_attr($status);?>"><?php echo esc_html(SWC_Helpers::statuses()[$status]);?></span><strong>Appointment #<?php echo absint($id);?></strong></header><div class="swc-appointment-grid"><p><b>Doctor</b><?php echo esc_html(get_the_author_meta('display_name',$doctor));?></p><p><b>Patient</b><?php echo esc_html(get_the_author_meta('display_name',$patient));?></p><p><b>Requested time</b><?php echo esc_html(SWC_Helpers::display_time(SWC_Helpers::meta($id,'preferred_at_utc'),$zone));?></p><p><b>Consultation</b><?php echo esc_html(ucwords(str_replace('-',' ',SWC_Helpers::meta($id,'consultation_type'))));?></p><p><b>Phone</b><a href="tel:<?php echo esc_attr(SWC_Helpers::meta($id,'phone'));?>"><?php echo esc_html(SWC_Helpers::meta($id,'phone'));?></a></p><p><b>WhatsApp</b><a href="<?php echo esc_url(SWC_Helpers::whatsapp(SWC_Helpers::meta($id,'whatsapp')));?>" target="_blank" rel="noopener noreferrer">Open WhatsApp</a></p></div><details><summary>Private request details</summary><p><?php echo nl2br(esc_html(SWC_Helpers::meta($id,'reason')));?></p><p><b>Duration:</b> <?php echo esc_html(SWC_Helpers::meta($id,'duration','Not provided'));?></p><?php if(SWC_Helpers::meta($id,'doctor_note')):?><p><b>Doctor note:</b> <?php echo nl2br(esc_html(SWC_Helpers::meta($id,'doctor_note')));?></p><?php endif;?></details><?php if('patient'===$role&&!in_array($status,array('cancelled','completed','declined'),true)):?><form action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><input type="hidden" name="action" value="swc_patient_cancel"><input type="hidden" name="appointment_id" value="<?php echo absint($id);?>"><?php wp_nonce_field('swc_patient_cancel_'.$id);?><button class="swc-link-button" type="submit">Cancel Request</button></form><?php elseif('doctor'===$role):?><?php echo $this->doctor_form($id);// phpcs:ignore ?><?php endif;?></article><?php return ob_get_clean();}
	private function doctor_form($id){ob_start();?><form class="swc-doctor-form" action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><input type="hidden" name="action" value="swc_doctor_update"><input type="hidden" name="appointment_id" value="<?php echo absint($id);?>"><?php wp_nonce_field('swc_doctor_update_'.$id);?><label>Status<select name="status"><option value="under-review">Under Review</option><option value="accepted">Accepted</option><option value="reschedule-requested">Reschedule Requested</option><option value="declined">Declined</option><option value="completed">Completed</option></select></label><label>Private administrative note<textarea name="doctor_note" maxlength="1000"></textarea></label><div class="swc-reschedule"><label>Proposed date<input type="date" name="new_date"></label><label>Proposed time<input type="time" name="new_time"></label><label>Time zone<select name="new_timezone"><?php foreach(SWC_Helpers::timezones() as $tz):?><option value="<?php echo esc_attr($tz);?>"><?php echo esc_html($tz);?></option><?php endforeach;?></select></label></div><button class="swc-button" type="submit">Update Appointment</button></form><?php return ob_get_clean();}
	public function availability(){if(!is_user_logged_in()||!SDD_Helpers::is_verified(get_current_user_id())){return '<div class="swc-notice">Verified doctor access is required.</div>';}$id=get_current_user_id();$days=(array)SWC_Helpers::doctor_meta($id,'available_days',array());$zone=SWC_Helpers::doctor_meta($id,'timezone','UTC');ob_start();?><main class="swc-shell"><header class="swc-page-head"><span>Clinic Schedule</span><h1>Doctor Availability</h1><p>Publish a basic availability window. Every appointment still requires individual confirmation.</p></header><form class="swc-form" action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><input type="hidden" name="action" value="swc_save_availability"><?php wp_nonce_field('swc_save_availability','swc_nonce');?><fieldset class="swc-wide"><legend>Available days</legend><div class="swc-days"><?php foreach(array('monday','tuesday','wednesday','thursday','friday','saturday','sunday') as $day):?><label><input type="checkbox" name="days[]" value="<?php echo esc_attr($day);?>" <?php checked(in_array($day,$days,true));?>><?php echo esc_html(ucfirst($day));?></label><?php endforeach;?></div></fieldset><label>Start time<input type="time" name="start_time" value="<?php echo esc_attr(SWC_Helpers::doctor_meta($id,'start_time'));?>"></label><label>End time<input type="time" name="end_time" value="<?php echo esc_attr(SWC_Helpers::doctor_meta($id,'end_time'));?>"></label><label>Time zone<select name="timezone"><?php foreach(SWC_Helpers::timezones() as $tz):?><option value="<?php echo esc_attr($tz);?>" <?php selected($zone,$tz);?>><?php echo esc_html($tz);?></option><?php endforeach;?></select></label><label>Appointment duration in minutes<input type="number" name="duration" min="10" max="180" value="<?php echo absint(SWC_Helpers::doctor_meta($id,'duration',30));?>"></label><div class="swc-checks swc-wide"><label><input type="checkbox" name="online" value="1" <?php checked(SWC_Helpers::doctor_meta($id,'online','0'),'1');?>> Online consultation available</label><label><input type="checkbox" name="in_person" value="1" <?php checked(SWC_Helpers::doctor_meta($id,'in_person','0'),'1');?>> In-person consultation available</label><label><input type="checkbox" name="accepting" value="1" <?php checked(SWC_Helpers::doctor_meta($id,'accepting','0'),'1');?>> Accepting new appointment requests</label><label><input type="checkbox" name="unavailable" value="1" <?php checked(SWC_Helpers::doctor_meta($id,'unavailable','0'),'1');?>> Temporarily unavailable</label></div><button class="swc-button" type="submit">Save Availability</button></form></main><?php return ob_get_clean();}
	public function augment($output,$tag){if('swc_worldwide_clinic'===$tag){$f=SPD_Helpers::founder();$phone=get_option('swc_clinic_phone',$f['phone']);$whatsapp=get_option('swc_clinic_whatsapp',$f['whatsapp']);$buttons='<div class="swc-contact">';if($phone){$buttons.='<a class="swc-button" href="tel:'.esc_attr(SWC_Helpers::phone($phone)).'">Phone</a>';}$wa=SWC_Helpers::whatsapp($whatsapp);if($wa){$buttons.='<a class="swc-button is-whatsapp" href="'.esc_url($wa).'" target="_blank" rel="noopener noreferrer">WhatsApp</a>';}$buttons.='</div>';return preg_replace('/<\/header>/',$buttons.'</header>',$output,1);}if('swc_my_appointments'===$tag&&is_user_logged_in()){$items=get_posts(array('post_type'=>SWC_Helpers::TYPE,'post_status'=>'publish','author'=>get_current_user_id(),'posts_per_page'=>50,'meta_key'=>'_swc_status','meta_value'=>'reschedule-requested'));if($items){$section='<section class="swc-reschedule-list"><h2>Reschedule Proposals</h2>';foreach($items as $item){$id=$item->ID;$zone=SWC_Helpers::meta($id,'patient_timezone','UTC');$section.='<article><p><strong>Appointment #'.absint($id).'</strong> — '.esc_html(SWC_Helpers::display_time(SWC_Helpers::meta($id,'proposed_at_utc'),$zone)).'</p><form action="'.esc_url(admin_url('admin-post.php')).'" method="post"><input type="hidden" name="action" value="swc_patient_accept_reschedule"><input type="hidden" name="appointment_id" value="'.absint($id).'">'.wp_nonce_field('swc_patient_accept_'.$id,'_wpnonce',true,false).'<button class="swc-button" type="submit">Accept Proposed Time</button></form></article>';}$section.='</section>';return str_replace('</main>',$section.'</main>',$output);} }return $output;}
}
